import java.util.*;
public class ArrayBasedList { private int[] a=new int[4]; private int size; public void add(int x){if(size==a.length)a=Arrays.copyOf(a,a.length*2);a[size++]=x;} public int removeLast(){if(size==0)throw new NoSuchElementException("empty list");return a[--size];} public boolean contains(int x){for(int i=0;i<size;i++)if(a[i]==x)return true;return false;} public String toString(){return Arrays.toString(Arrays.copyOf(a,size));} public static void run(){ArrayBasedList l=new ArrayBasedList();l.add(4);l.add(8);l.add(15);System.out.println("Array list after inserts: "+l);System.out.println("find 8="+l.contains(8)+", removeLast="+l.removeLast()+", now "+l);System.out.println("Invariant: elements occupy indexes 0..size-1; add amortized O(1), find O(n).\n");} public static void main(String[] args){run();}}
